from rich.cells import cell_len

def test_zwj_width():
    # A + ZWJ + B
    text = "A\u200dB"
    width = cell_len(text)
    print(f"Text: {text!r}, Width: {width}")
    assert width == 2, f"Expected width 2 for {text!r}, got {width}"

if __name__ == "__main__":
    try:
        test_zwj_width()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")

